 'sin_add': lambda p: -(p[0]+p[1]*A**p[2]) + p[3]*np.sin(p[4]*t+p[5]),
 'sin_mult': lambda p: -(p[0]+p[1]*A**p[2])*(1+p[3]*np.sin(p[4]*t+p[5])),
